    freq_dict1 = {}
    freq_dict2 = {}

    # Iterate through each character in the strings
    for char in str1:
        if char.isalnum():  # Consider only alphanumeric characters
            char = char.lower()  # Make the comparison case insensitive
            if char in freq_dict1:
