    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def is_palindromic(num):
    return str(num) == str(num)[::-1]

def has_only_odd_digits(num):
    return all(digit % 2 != 0 for digit in str(num))

def print_primes(n):
    if n < 2:
        return
    if is_prime(n) and not is_palindromic(n) and not has_only_odd_digits(n):
        print(n)
    print_primes(n - 1)

# Example usage
