To store the inventory of an online grocery store, we can use a dictionary data structure in Python. Each item in the inventory will be represented as a dictionary with the following keys:

1. Name: A string with a maximum length of 50 characters.
2. Quantity: An integer ranging from 1 to 1000.
3. Price: A float ranging from $0.01 to $1000.
4. Nutritional information: A dictionary containing the following keys:
   - Calories: An integer representing the number of calories per unit.
   - Carbohydrates: A float representing the amount of carbohydrates per unit.
   - Vitamins: A dictionary containing the names and amounts of vitamins per unit.

Here is the implementation of the data structure:

```python
class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, name, quantity, price, nutritional_info):
        if name in self.items:
            raise ValueError("Item already exists in the inventory")
        if not (1 <= quantity <= 1000):
            raise ValueError("Invalid quantity")
        if not (0.01 <= price <= 1000):
            raise ValueError("Invalid price")
        if not isinstance(nutritional_info, dict):
            raise ValueError("Invalid nutritional information")
        if not isinstance(nutritional_info.get("Calories", 0), int):
            raise ValueError("Invalid calories")
        if not isinstance(nutritional_info.get("Carbohydrates", 0), (int, float)):
            raise ValueError("Invalid carbohydrates")
        if not isinstance(nutritional_info.get("Vitamins", {}), dict):
            raise ValueError("Invalid vitamins")
        self.items[name] = {
            "Quantity": quantity,
            "Price": price,
            "NutritionalInfo": nutritional_info
        }

    def remove_item(self, name):
        if name not in self.items:
            raise ValueError("Item does not exist in the inventory")
        del self.items[name]

    def update_quantity(self, name, quantity):
        if name not in self.items:
            raise ValueError("Item does not exist in the inventory")
        if not (1 <= quantity <= 1000):
            raise ValueError("Invalid quantity")
        self.items[name]["Quantity"] = quantity

    def update_price(self, name, price):
        if name not in self.items:
            raise ValueError("Item does not exist in the inventory")
        if not (0.01 <= price <= 1000):
            raise ValueError("Invalid price")
        self.items[name]["Price"] = price

    def get_nutritional_info(self, name):
        if name not in self.items:
            raise ValueError("Item does not exist in the inventory")
        return self.items[name]["NutritionalInfo"]
```

