def generate_palindromic_primes(start, end):
    palindromic_primes = []
    for num in range(start, end + 1):
        if is_prime(num) and is_palindrome(num):
            palindromic_primes.append(num)
    return palindromic_primes

def generate_random_palindromic_primes(start, end, count):
    palindromic_primes = generate_palindromic_primes(start, end)
    if len(palindromic_primes) < count:
