```python
import json
import re
import ajv

def validate_and_format_json(data):
    # Define the schema
    schema = {
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "age": {"type": "integer", "minimum": 1},
            "address": {
                "type": "object",
                "properties": {
                    "street": {"type": "string"},
                    "city": {"type": "string"},
                    "state": {"type": "string"},
                    "country": {"type": "string"}
                },
                "required": ["street", "city", "state", "country"]
            },
            "contact": {
                "type": "object",
                "properties": {
                    "email": {"type": "string", "format": "email"},
                    "phone": {"type": "string", "pattern": r"^\+\d{1,3}\s\d{3}-\d{3}-\d{4}$"}
                },
                "required": ["email", "phone"]
            },
            "hobbies": {"type": "array", "items": {"type": "string"}},
            "languages": {
                "type": "object",
                "properties": {
                    "english": {"type": "boolean"},
                    "spanish": {"type": "boolean"},
                    "french": {"type": "boolean"}
                },
                "required": ["english", "spanish", "french"]
            },
            "education": {
                "type": "object",
                "properties": {
                    "degree": {"type": "string"},
                    "major": {"type": "string"},
                    "university": {"type": "string"}
                },
                "required": ["degree", "major", "university"]
            },
            "experience": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "company": {"type": "string"},
                        "position": {"type": "string"},
                        "years": {"type": "integer", "minimum": 1}
                    },
                    "required": ["company", "position", "years"]
                }
            }
        },
        "required": ["name", "age", "address", "contact", "hobbies", "languages", "education", "experience"]
    }

    # Validate the JSON data against the schema
    validator = ajv.compile(schema)
    if not validator(data):
        errors = validator.errors
        error_messages = []
        for error in errors:
            if error["keyword"] == "format":
                error_messages.append(f"Invalid format for '{error['dataPath']}': {error['message']}")
            elif error["keyword"] == "pattern":
                error_messages.append(f"Invalid format for '{error['dataPath']}': {error['message']}")
            else:
                error_messages.append(f"Validation error for '{error['dataPath']}': {error['message']}")
        raise ValueError("\n".join(error_messages))

    # Format the JSON data as a string
    formatted_data = json.dumps(data, indent=4)

    return formatted_data
```

