def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = math.isqrt(n)
    for i in range(3, sqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_primes():
    primes = []
    while len(primes) < 20:
        primes = []
        for num in range(100, 501):
            if is_prime(num) and num not in primes:
                primes.append(num)
                if len(primes) == 20 and sum(primes) % 10 == 0:
                    return primes
        primes = []

# Test cases
primes = generate_primes()
assert len(set(primes)) == 20, "Not all primes are unique"
assert sum(primes) % 10 == 0, "Sum of primes is not divisible by 10"
print(primes)
```

