def sum_lists(list1, list2):
    if len(list1) > 1000 or len(list2) > 1000:
        raise ValueError("Lists should not have more than 1000 elements")
    if len(list1) != len(list2):
        raise ValueError("Lists should have the same length")
    if not all(isinstance(i, int) and i > 0 for i in list1 + list2):
