```python
import random
import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = math.isqrt(n)
    for i in range(3, sqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_prime(min_val, max_val):
    while True:
        num = random.randint(min_val, max_val)
        if is_prime(num):
            return num

def find_difference():
    min_val = -1000
    max_val = 1000
    prime1 = generate_prime(min_val, max_val)
    prime2 = generate_prime(min_val, max_val)
    diff = abs(prime1 - prime2)

    while True:
        random_prime = generate_prime(1, 100)
        if diff % random_prime == 0:
            return round(diff)
        else:
            prime1 = generate_prime(min_val, max_val)
            prime2 = generate_prime(min_val, max_val)
            diff = abs(prime1 - prime2)

# Example usage
print(find_difference())
```

