import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def generate_pattern(rows, cols):
    num = 2
    pattern = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            while not is_prime(num):
                num += 1
            pattern[i][j] = num
            num += 1

    for i in range(rows):
        if i % 2 == 0:
            for j in range(cols):
                print(pattern[i][j], end=" ")
        else:
            for j in range(cols - 1, -1, -1):
                print(pattern[i][j], end=" ")
        print()

# Example usage
generate_pattern(10, 10)
```

