    # Calculate the middle index using integer division
    mid = len(arr) // 2

    # If the target value is at the middle index, return the index
    if arr[mid] == target:
        return mid

    # If the target value is less than the middle element, search the left half recursively
    if target < arr[mid]:
        return binary_search(arr[:mid], target)

    # If the target value is greater than the middle element, search the right half recursively
    else:
        left_half_result = binary_search(arr[:mid], target)
        if left_half_result != -1:
            return left_half_result
        else:
            return mid + binary_search(arr[mid+1:], target)

# Test cases
