def matrix_product(matrix):
    # Check if matrix is empty
    if not matrix:
        return 1

    # Check if matrix is not a list or if it contains non-list elements
    if not all(isinstance(row, list) for row in matrix):
        return -1

    # Check if any row is empty or contains non-integer elements
    for row in matrix:
        if not row or not all(isinstance(element, int) for element in row):
            return -1

    # Calculate the product of all elements
    product = 1
    for row in matrix:
        for element in row:
            if element <= 0:
                return -1
            product *= element

    return product
