def df_to_dict(df, columns):
    if len(columns) == 1:
        return df.set_index(columns[0])['v3'].to_dict()
    else:
        return {k: df_to_dict(df[df['name'] == k], columns[1:]) for k in df['name'].unique()}

result = df_to_dict(df, df.columns[:-1])
