import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    # Check if the process is running
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            # Process found, terminate it
            try:
                proc.terminate()
                proc.wait(timeout=5)
                if proc.is_running():
                    proc.kill()
                print("Process found. Restarting", process_name)
            except Exception as e:
                print("Error while terminating the process:", e)
                return
            break
    else:
        print("Process not found. Starting", process_name)

    # Start the process
    try:
        subprocess.Popen([process_name], shell=True)
    except Exception as e:
        print("Error while starting the process:", e)
```

