from functools import reduce
import operator

def task_func(list_of_pairs):
    if not isinstance(list_of_pairs, list):
        raise TypeError("Input must be a list of tuples")
    if not all(isinstance(pair, tuple) and len(pair) == 2 for pair in list_of_pairs):
        raise TypeError("Input must be a list of tuples with exactly two elements")

    second_values = np.array([pair[1] for pair in list_of_pairs])
