```python
import csv
import io
from django.http import HttpRequest, FileResponse

def task_func(request, header, csv_data):
    # Validate input
    if not isinstance(header, list) or not all(isinstance(i, str) for i in header):
        return HttpResponse("Invalid header. It should be a list of strings.", status=400)
    if not isinstance(csv_data, list) or not all(isinstance(i, list) for i in csv_data):
        return HttpResponse("Invalid csv_data. It should be a list of lists.", status=400)

    # Validate that each row in csv_data has the same number of elements as the header
    if not all(len(row) == len(header) for row in csv_data):
        return HttpResponse("Each row in csv_data should have the same number of elements as the header.", status=400)

    # Create a CSV file in memory
    csv_file = io.StringIO()
    writer = csv.writer(csv_file)

    # Write the header
    writer.writerow(header)

    # Write the data
    for row in csv_data:
        try:
            writer.writerow(row)
        except Exception as e:
            return HttpResponse(f"Error writing row to CSV: {e}", status=500)

    # Rewind the file
    csv_file.seek(0)

    # Create a FileResponse
    response = FileResponse(csv_file, as_attachment=True, filename='data.csv')

    # Set the content type
    response['Content-Type'] = 'text/csv'

    # Return the response
