```python
import zipfile
import io
from django.http import FileResponse, HttpRequest
from django.conf import settings

def task_func(request, file_paths):
    if not file_paths:
        return HttpResponse("No files provided for zipping.")

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, 'w') as zip_file:
        for file_path in file_paths:
            if not settings.BASE_DIR.joinpath(file_path).exists():
                return HttpResponse(f"File {file_path} does not exist or is not accessible.")
            zip_file.write(settings.BASE_DIR.joinpath(file_path), arcname=file_path)

    zip_buffer.seek(0)
    response = FileResponse(zip_buffer, as_attachment=True, filename='files.zip')
    response['Content-Disposition'] = 'attachment; filename="files.zip"'
    return response
```
