import requests
import os
import zipfile

def task_func(url, destination_directory, headers=None):
    # Check if the URL is HTTPS
    if not url.startswith('https'):
        return "Error: URL must be a secure HTTPS link."

    # Download the zip file
    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()  # Raise an HTTPError if the response was unsuccessful
    except requests.exceptions.HTTPError as errh:
        return f"Error: HTTP Error occurred: {errh}"
    except requests.exceptions.RequestException as err:
        return f"Error: General Error occurred: {err}"

    # Check if the destination directory exists
    if not os.path.exists(destination_directory):
        return f"Error: Destination directory {destination_directory} does not exist."

    # Save the zip file
    try:
        with open(os.path.join(destination_directory, 'file.zip'), 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except Exception as e:
        return f"Error: Failed to save the zip file: {e}"

    # Extract the zip file
    try:
        with zipfile.ZipFile(os.path.join(destination_directory, 'file.zip'), 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
        # Get the list of extracted files
        extracted_files = [f for f in os.listdir(destination_directory) if os.path.isfile(os.path.join(destination_directory, f))]
        return extracted_files
    except zipfile.BadZipFile:
        return "Error: The downloaded file is not a valid zip file."
    except Exception as e:
        return f"Error: Failed to extract the zip file: {e}"
