import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}

ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}

class JSONPostHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        content_type = self.headers.get('content-type')
        if content_type != 'application/json':
            self.send_error(400, 'Content-Type header is not application/json')
            return

        length = int(self.headers.get('content-length'))
        post_data = self.rfile.read(length).decode('utf-8')

        try:
            json_data = json.loads(post_data)
        except json.JSONDecodeError:
            self.send_error(400, 'Invalid JSON')
            return

        if 'data' not in json_data:
            self.send_error(400, 'No data key in request')
            return

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))

def task_func():
    return JSONPostHandler
```

