```python
class ResultProcessor:
    def run(self, result, per_page=None):
        if 'metadata' not in result or 'page' not in result['metadata']:
            raise ValueError("'metadata' dictionary must contain a 'page' key")

        data = result.get('data', [])
        page = result['metadata']['page']

        if not data:
            return {'data': [], 'metadata': {'page': page, 'perPage': 0}}

        if per_page is None:
            per_page = len(data)

        start_index = (page - 1) * per_page
        end_index = start_index + per_page

        if end_index > len(data):
            end_index = len(data)

        return {
            'data': data[start_index:end_index],
            'metadata': {
                'page': page,
                'perPage': len(data[start_index:end_index])
            }
        }
```

