from typing import List, Dict

class Queue:
    def __init__(self, name: str, penalty: int):
        self.name = name
        self.penalty = penalty

class QueueDelta:
    def calculate(self, old_queues: List[Queue], new_queues: List[Queue]) -> Dict[str, List[Queue]]:
        if not all(isinstance(queue, Queue) for queue in old_queues + new_queues):
            raise ValueError("Invalid input: All elements in the lists must be Queue objects.")

        old_queue_names = {queue.name: queue for queue in old_queues}
        new_queue_names = {queue.name: queue for queue in new_queues}

        added = [new_queue_names[name] for name in set(new_queue_names) - set(old_queue_names)]
        removed = [old_queue_names[name] for name in set(old_queue_names) - set(new_queue_names)]
        penalty_updated = [queue for queue in new_queue_names.values() if queue.name in old_queue_names and old_queue_names[queue.name].penalty != queue.penalty]

        return {"added": added, "removed": removed, "penalty_updated": penalty_updated}

class OnAgentUpdatedManager:
    def __init__(self, add_to_queue_action, remove_from_queue_action, update_penalty_action):
        self.add_to_queue_action = add_to_queue_action
        self.remove_from_queue_action = remove_from_queue_action
        self.update_penalty_action = update_penalty_action

    def on_agent_updated(self, agent):
        if not hasattr(agent, "queues"):
            raise ValueError("Invalid input: Agent object must have a 'queues' attribute.")

        queue_delta = QueueDelta().calculate(agent.old_queues, agent.queues)

        for queue in queue_delta["added"]:
            self.add_to_queue_action(agent, queue)

        for queue in queue_delta["removed"]:
            self.remove_from_queue_action(agent, queue)

        for queue in queue_delta["penalty_updated"]:
            self.update_penalty_action(agent, queue)
```

