def string_operations(s, operations):
    def slice_operation(start, end):
        try:
            return s[start:end]
        except IndexError:
            return ""

    def check_operation(sub):
        return sub in s

    def concat_operation(str_to_add):
        return s + str_to_add

    def format_operation(values):
        if len(values) != s.count("{}"):
            raise ValueError("Invalid number of values for formatting")
        return s.format(*values)

    results = []
    for operation in operations:
        op_name = operation[0]
        if op_name == "slice":
            if len(operation) != 3:
                raise ValueError("Invalid number of parameters for slice operation")
            start, end = operation[1], operation[2]
            results.append(slice_operation(start, end))
        elif op_name == "check":
            if len(operation) != 2:
                raise ValueError("Invalid number of parameters for check operation")
            sub = operation[1]
            results.append(check_operation(sub))
        elif op_name == "concat":
            if len(operation) != 2:
                raise ValueError("Invalid number of parameters for concat operation")
            str_to_add = operation[1]
            results.append(concat_operation(str_to_add))
        elif op_name == "format":
            if len(operation) != 2:
                raise ValueError("Invalid number of parameters for format operation")
            values = operation[1]
            results.append(format_operation(values))
        else:
            raise ValueError(f"Unsupported operation: {op_name}")

    return results
