```python
import pandas as pd
import catboost
from typing import Dict

class CatBoostClassifierWrapper:
    name = "Catboost Classifier"
    primary_type = "classification"
    secondary_type = "None"
    tertiary_type = "tree"

    hyperparameters = {
        "n_estimators": 50,
        "max_depth": 3,
        "learning_rate": 0.1
    }

    def __init__(self, n_estimators=50, max_depth=3, learning_rate=0.1):
        self.n_estimators = n_estimators
        self.max_depth = max_depth
        self.learning_rate = learning_rate
        self.model = catboost.CatBoostClassifier(
            iterations=self.n_estimators,
            depth=self.max_depth,
            learning_rate=self.learning_rate
        )

    def fit(self, X: pd.DataFrame, y: pd.Series):
        if not isinstance(X, pd.DataFrame) or not isinstance(y, pd.Series):
            raise ValueError("X must be a pandas DataFrame and y must be a pandas Series")
        self.model.fit(X, y)

    def predict(self, X: pd.DataFrame):
        if not isinstance(X, pd.DataFrame):
            raise ValueError("X must be a pandas DataFrame")
        if set(X.columns) != set(self.model.feature_names_):
            raise ValueError("X must have the same feature columns as the training data")
        return pd.Series(self.model.predict(X))

    def score(self, X: pd.DataFrame, y: pd.Series):
        if not isinstance(X, pd.DataFrame) or not isinstance(y, pd.Series):
            raise ValueError("X must be a pandas DataFrame and y must be a pandas Series")
        return self.model.score(X, y)

    def get_params(self) -> Dict[str, int]:
        return {
            "n_estimators": self.n_estimators,
            "max_depth": self.max_depth,
            "learning_rate": self.learning_rate
        }
```

