import logging
import time
from datetime import datetime, timedelta

class NoDevice(Exception):
    pass

def unix_to_human(unix_timestamp, separator='-'):
    dt = datetime.utcfromtimestamp(int(unix_timestamp)).strftime('%Y%m%d%H%M%S')
    return separator.join([dt[:4], dt[4:6], dt[6:8], dt[8:10], dt[10:12], dt[12:]])

def human_to_unix(human_time, separator='-'):
    dt = datetime.strptime(human_time.replace(separator, ''), '%Y%m%d%H%M%S')
    return int(time.mktime(dt.timetuple()))

def get_day_timestamps():
    now = datetime.utcnow()
    start_of_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
    end_of_day = start_of_day + timedelta(days=1) - timedelta(seconds=1)
    return int(time.mktime(start_of_day.timetuple())), int(time.mktime(end_of_day.timetuple()))

def clean_ids(raw_data):
    return {k: v.strip() for k, v in raw_data.items() if 'id' in k}

def extract_data(server_response):
    data = {}
    errors = []

    try:
        response_data = server_response.json()

        if 'devices' not in response_data:
            raise NoDevice('No device data available')

        for device in response_data['devices']:
            device_id = device['id'].strip()
            data[device_id] = {
                'module_id': device['module_id'].strip(),
                'status': device['status'],
                'last_update': unix_to_human(device['last_update'])
            }

    except (KeyError, ValueError) as e:
        logging.debug(f'Error extracting data: {e}')
        errors.append(str(e))

    except NoDevice as e:
        logging.debug(f'No device data available: {e}')
        errors.append(str(e))

    if errors:
        raise NoDevice(', '.join(errors))

    return data
