import torch
import torch.nn.functional as F

class ImageDiffusionSampler:
    def __init__(self, diffusion_model):
        self.diffusion_model = diffusion_model
        self.device = next(self.diffusion_model.parameters()).device

    def to(self, device):
        self.diffusion_model = self.diffusion_model.to(device)
        self.device = device

    def sample_image(self, num_steps, initial_latent=None):
        if initial_latent is None:
            initial_latent = torch.randn((1, self.diffusion_model.in_channels, self.diffusion_model.image_size, self.diffusion_model.image_size), device=self.device)

        latent = initial_latent
        for i in range(num_steps):
            timestep = num_steps - i
            latent = self.add_noise(latent, timestep)
            latent = self.diffusion_model(latent, timestep)

        return latent

    def apply_mask(self, noisy_latent, original_latent, mask, timestep):
        return noisy_latent * (1 - mask) + original_latent * mask

    def add_noise(self, latent, timestep, noise=None):
