        sqrt_alphas_cumprod_t = self.diffusion_model.sqrt_alphas_cumprod[timestep]
        sqrt_one_minus_alphas_cumprod_t = self.diffusion_model.sqrt_one_minus_alphas_cumprod[timestep]

        return sqrt_alphas_cumprod_t * latent + sqrt_one_minus_alphas_cumprod_t * noise
