def get_primes(n):
    sieve = [True] * (n+1)
    for x in range(2, int(n**0.5) + 1):
        if sieve[x]:
            for u in range(x*x, n+1, x):
                sieve[u] = False
    return [x for x in range(2, n) if sieve[x]]

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def min_elements_to_remove(data):
    total = sum(data)
    primes = get_primes(total+1)
    for prime in primes:
        if total - prime < 0:
            continue
        diff = total - prime
        indices = []
        for i in range(len(data)):
            if data[i] <= diff:
                diff -= data[i]
                indices.append(i+1)
            if diff == 0:
                break
        if diff == 0:
            return (len(indices), indices)
    return (-1, [])

