```python
class Airport:
    def __init__(self, flights, airports):
        self.flights = flights
        self.airports = airports

    def validate_flight(self, flight):
        if not isinstance(flight["airline"], str):
            return False
        if not isinstance(flight["flight_number"], int):
            return False
        if not isinstance(flight["destination"], str):
            return False
        if not isinstance(flight["gate"], int):
            return False
        if not isinstance(flight["departure_time"], (int, float)):
            return False
        return True

    def schedule_by_flight(self):
        valid_flights = [flight for flight in self.flights if self.validate_flight(flight)]
        if not valid_flights:
            print("No valid flights found.")
            return

        valid_flights.sort(key=lambda x: x["flight_number"])
        self.print_schedule(valid_flights)

    def schedule_by_time(self):
        valid_flights = [flight for flight in self.flights if self.validate_flight(flight)]
        if not valid_flights:
            print("No valid flights found.")
            return

        valid_flights.sort(key=lambda x: x["departure_time"])
        self.print_schedule(valid_flights)

    def print_schedule(self, flights):
        print("Flight\tDestination\tGate\tTime")
        for flight in flights:
            destination = self.airports.get(flight["destination"], "Unknown")
            print(f"{flight['flight_number']}\t{destination}\t{flight['gate']}\t{flight['departure_time']}")

