```python
import json
import requests
from bs4 import BeautifulSoup

def get_one_page(url, headers):
    try:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.text
        else:
            print(f"Failed to get the page: {url}")
            return None
    except requests.exceptions.RequestException as e:
        print(f"Error occurred: {e}")
        return None

def parse_one_page(html):
    soup = BeautifulSoup(html, 'html.parser')
    movies = soup.find_all('dd')

    for movie in movies:
        rank = movie.find('i', class_='board-index').text
        cover_image_url = movie.find('img')['data-src']
        title = movie.find('p', class_='name').find('a').text
        actors = movie.find('p', class_='star').text.replace('Main Actors: ', '')
        release_time = movie.find('p', class_='releasetime').text.replace('Release Time: ', '')
        rating = movie.find('p', class_='score').find('i', class_='integer').text + '.' + movie.find('p', class_='score').find('i', class_='fraction').text

        yield {
            'rank': rank,
            'cover_image_url': cover_image_url,
            'title': title,
            'actors': actors,
            'release_time': release_time,
            'rating': rating
        }

def write_to_file(content):
    with open('top_100_movies.json', 'w') as f:
        json.dump(content, f, indent=2)

def main(offset):
    url = f'http://fictional-movie-site.com/board/4?offset={offset}'
    headers = {'User-Agent': 'Mozilla/5.0'}

    html = get_one_page(url, headers)
    if html:
        movies = list(parse_one_page(html))
        write_to_file(movies)

if __name__ == '__main__':
    for offset in range(0, 100, 10):
        main(offset)
```

This program uses the `requests` library to send GET requests and the `BeautifulSoup` library to parse the HTML content. The `get_one_page` function sends a GET request to the given URL with the specified headers and returns the HTML content if the response status is 200, otherwise returns `None`. The `parse_one_page` function parses the HTML content and yields dictionaries containing the movie details. The `write_to_file` function writes the given content to a file in JSON format. The `main` function orchestrates the scraping process for a single page by constructing the URL with the given offset, calling `get_one_page` and `parse_one_page`, and then writing the results to a file. The main block iterates over the necessary offsets to scrape the top 100 movies.

