class FinancialTransaction:
    def __init__(self, message_type, sender=None, receiver=None, amount=None, currency=None, transaction_id=None, success=None):
        self.message_type = message_type
        self.sender = sender
        self.receiver = receiver
        self.amount = amount
        self.currency = currency
        self.transaction_id = transaction_id
        self.success = success

    @property
    def sender(self):
        return self._sender

    @sender.setter
    def sender(self, value):
        if self.message_type == 'Transaction' and value is None:
            raise ValueError("Sender is required for a Transaction message")
        self._sender = value

    @property
    def receiver(self):
        return self._receiver

    @receiver.setter
    def receiver(self, value):
        if self.message_type == 'Transaction' and value is None:
            raise ValueError("Receiver is required for a Transaction message")
        self._receiver = value

    @property
    def amount(self):
        return self._amount

    @amount.setter
    def amount(self, value):
        if self.message_type == 'Transaction' and (value is None or value < 0):
            raise ValueError("Amount must be a non-negative number for a Transaction message")
        self._amount = value

    @property
    def currency(self):
        return self._currency

    @currency.setter
    def currency(self, value):
        if self.message_type == 'Transaction' and value is None:
            raise ValueError("Currency is required for a Transaction message")
        self._currency = value

    @property
    def transaction_id(self):
        return self._transaction_id

    @transaction_id.setter
    def transaction_id(self, value):
        if self.message_type == 'Transaction' and value is None:
            raise ValueError("Transaction ID is required for a Transaction message")
        if self.message_type == 'Confirmation' and value is None:
            raise ValueError("Transaction ID is required for a Confirmation message")
        self._transaction_id = value

    @property
    def success(self):
        return self._success

    @success.setter
    def success(self, value):
        if self.message_type == 'Confirmation' and value is None:
            raise ValueError("Success status is required for a Confirmation message")
        self._success = value

    def is_valid(self):
        if self.message_type == 'Transaction':
            return all([self.sender, self.receiver, self.amount >= 0, self.currency, self.transaction_id])
        elif self.message_type == 'Confirmation':
            return all([self.transaction_id, isinstance(self.success, bool)])
        else:
            return False
