    def test_replay_buffer(self):
        capacity = 10
        buffer = ReplayBuffer(capacity)
        transition = Transition(state=(np.array([1]), np.array([1])), action=0, reward=1, next_state=(np.array([2]), np.array([2])), done=False)
        buffer.add(transition)
        self.assertEqual(len(buffer.buffer), 1)
        self.assertEqual(buffer.buffer[0].state, (np.array([1]), np.array([1])))
        self.assertEqual(buffer.buffer[0].action, 0)
        self.assertEqual(buffer.buffer[0].reward, 1)
        self.assertEqual(buffer.buffer[0].next_state, (np.array([2]), np.array([2])))
        self.assertEqual(buffer.buffer[0].done, False)

