class JobSystem:
    def __init__(self):
        self.jobs = {}

    def job(self, depends_on=None, desc=None):
        def decorator(func):
            self.jobs[func.__name__] = {
                'func': func,
                'depends_on': depends_on,
                'desc': desc
            }
            return func
        return decorator

    def run_job(self, job_name):
        if job_name not in self.jobs:
            raise ValueError(f"Job '{job_name}' does not exist.")

        job = self.jobs[job_name]
        if job['depends_on']:
            self.run_job(job['depends_on'])

        job['func']()

    def list_jobs(self):
        for job_name, job in self.jobs.items():
            depends_on = job['depends_on'] if job['depends_on'] else 'None'
            print(f"Job: {job_name}, Desc: {job['desc']}, Depends on: {depends_on}")

# Example usage:
