class LoadBalancer:
    def __init__(self, n: int):
        self.n = n
        self.loads = []

    def add_load(self):
        self.loads = [int(input(f"Enter load for server {i+1}: ")) for i in range(self.n)]

    def calculate_balance_moves(self) -> int:
        total_load = sum(self.loads)
        avg_load = total_load // self.n
        excess_load = [load - avg_load for load in self.loads]

        excess_load.sort()
        moves = 0
        while excess_load and excess_load[0] < 0:
            excess_load.append(excess_load.pop(0) + 1)
            moves += 1

        if sum(excess_load) != 0:
            return -1
        else:
            return moves

def main():
    while True:
        n = int(input("Enter the number of servers (-1 to quit): "))
        if n == -1:
            break

        lb = LoadBalancer(n)
        lb.add_load()
        result = lb.calculate_balance_moves()
        print(f"Minimum number of moves required to balance the servers: {result}")

if __name__ == "__main__":
    main()
