Here's the implementation of the `secrets_manager` module:

```python
import boto3
from botocore.exceptions import ClientError

class SecretsManagerError(Exception):
    pass

class SecretsManager:
    def __init__(self, region_name):
        self.client = boto3.client('secretsmanager', region_name=region_name)

    def write_secret(self, secret_name, secret_value):
        try:
            response = self.client.create_secret(
                Name=secret_name,
                SecretString=secret_value
            )
            return response['ARN']
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceExistsException':
                self.update_secret(secret_name, secret_value)
            else:
                raise SecretsManagerError(f"Failed to write secret: {str(e)}")

    def update_secret(self, secret_name, secret_value):
        try:
            response = self.client.update_secret(
                SecretId=secret_name,
                SecretString=secret_value
            )
            return response['ARN']
        except ClientError as e:
            raise SecretsManagerError(f"Failed to update secret: {str(e)}")

    def read_secret(self, secret_name):
        try:
            response = self.client.get_secret_value(SecretId=secret_name)
            return response['SecretString']
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                raise SecretsManagerError(f"Secret '{secret_name}' not found")
            else:
                raise SecretsManagerError(f"Failed to read secret: {str(e)}")
```

