```python
import random

def get_user_choice():
    while True:
        user_choice = input("Enter your choice (rock, paper, scissors) or type 'exit' to quit: ").lower()
        if user_choice == 'exit':
            return None
        elif user_choice in ['rock', 'paper', 'scissors']:
            return user_choice
        else:
            print("Invalid input. Please enter a valid choice.")

def get_computer_choice():
    choices = ['rock', 'paper', 'scissors']
    return random.choice(choices)

def determine_winner(user_choice, computer_choice):
    if user_choice == computer_choice:
        return 'draw'
    elif (user_choice == 'rock' and computer_choice == 'scissors') or \
         (user_choice == 'scissors' and computer_choice == 'paper') or \
         (user_choice == 'paper' and computer_choice == 'rock'):
        return 'user'
    else:
        return 'computer'

def main():
    wins = losses = draws = 0

    print("Welcome to Rock-Paper-Scissors!")
    print("Enter 'rock', 'paper', or 'scissors' to make your choice.")
    print("Type 'exit' to quit the game.")

    while True:
        user_choice = get_user_choice()
        if user_choice is None:
            break

        computer_choice = get_computer_choice()

        winner = determine_winner(user_choice, computer_choice)

        if winner == 'user':
            print(f"You chose {user_choice}, and the computer chose {computer_choice}. You win!")
            wins += 1
        elif winner == 'computer':
            print(f"You chose {user_choice}, and the computer chose {computer_choice}. You lose.")
            losses += 1
        else:
            print(f"You chose {user_choice}, and the computer also chose {computer_choice}. It's a draw.")
            draws += 1

    print(f"\nGame statistics:")
    print(f"Wins: {wins}")
    print(f"Losses: {losses}")
    print(f"Draws: {draws}")

if __name__ == "__main__":
    main()
```

This program defines functions to handle user input, computer choice, and determining the winner. The main function initializes the game, keeps track of the statistics, and displays the results. The program continues until the user decides to exit by typing 'exit'.

