To create a Python Django application that allows users to search for wallpapers from the Wallhaven website, follow these steps:

1. Install Django and create a new project:

```bash
pip install django
django-admin startproject wallhaven_search
cd wallhaven_search
```

2. Create a new app called `wallpapers`:

```bash
python manage.py startapp wallpapers
```

3. Add the `wallpapers` app to the `INSTALLED_APPS` list in `wallhaven_search/settings.py`:

```python
INSTALLED_APPS = [
    # ...
    'wallpapers',
]
```

4. In `wallpapers/forms.py`, create the `WallpaperForm`:

```python
from django import forms

class WallpaperForm(forms.Form):
    search_phrase = forms.CharField(max_length=255, required=False)
    random = forms.BooleanField(required=False)
```

5. In `wallpapers/views.py`, create the `wallpaper` view function and the `convert_images` helper function:

```python
import base64
import io
import json
import requests
from PIL import Image
from django.http import JsonResponse
from django.shortcuts import render
from .forms import WallpaperForm

def convert_images(search_phrase, random):
    url = f"https://wallhaven.cc/api/v1/search?q={search_phrase}&purity=100&categories=111&sorting=random" if not random else f"https://wallhaven.cc/api/v1/random?purity=100&categories=111&count=10"
    response = requests.get(url)
    if response.status_code != 200:
        return []

    images = []
    for image_data in response.json()['data']:
        img_url = image_data['path']
        img_ext = img_url.split('.')[-1]
        img_response = requests.get(f"https://w.wallhaven.cc/full/{img_url}.{img_ext}")
        if img_response.status_code == 200:
            img = Image.open(io.BytesIO(img_response.content))
            buffer = io.BytesIO()
            img.save(buffer, format=img_ext)
            img_str = base64.b64encode(buffer.getvalue()).decode()
            images.append((img_ext, img_str))
    return images

def wallpaper(request):
    if request.method == 'POST' and request.is_ajax():
        form = WallpaperForm(request.POST)
        if form.is_valid():
            search_phrase = form.cleaned_data['search_phrase']
            random = form.cleaned_data['random']
            images = convert_images(search_phrase, random)
            return JsonResponse({'images': images})
    else:
        form = WallpaperForm()

    return render(request, 'home.html', {'form': form})
```

6. In `wallpapers/templates/home.html`, create the form and the AJAX script:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Wallhaven Search</title>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
</head>
<body>
    <form id="wallpaper-form" method="post">
        {% csrf_token %}
        {{ form.as_p }}
        <button type="submit">Search</button>
    </form>
    <div id="search-results"></div>

    <script>
        $(document).ready(function() {
            $('#wallpaper-form').on('submit', function(e) {
                e.preventDefault();
                $.ajax({
                    type: 'POST',
                    url: $(this).attr('action'),
                    data: $(this).serialize(),
                    beforeSend: function() {
                        $('#search-results').html('<p>Loading...</p>');
                    },
                    success: function(response) {
                        $('#search-results').html('');
                        for (let i = 0; i < response.images.length; i++) {
                            const [ext, img_str] = response.images[i];
                            $('#search-results').append(`<img src="data:image/${ext};base64,${img_str}" />`);
                        }
                    },
                    error: function() {
                        $('#search-results').html('<p>Error fetching images. Please try again.</p>');
                    }
                });
            });
        });
    </script>
</body>
</html>
```

