import math

def read_coordinates(filename):
    try:
        with open(filename, 'r') as file:
            coordinates = []
            for line in file:
                line = line.strip()
                if line:
                    coordinates.append(list(map(int, line.split(','))))
            return coordinates
    except FileNotFoundError:
        print(f"The file '{filename}' was not found.")
        return []

def calculate_median(coordinates):
    flattened_coordinates = [item for sublist in coordinates for item in sublist]
    flattened_coordinates.sort()
    length = len(flattened_coordinates)
    if length % 2 == 0:
        median = (flattened_coordinates[length // 2 - 1] + flattened_coordinates[length // 2]) / 2
    else:
        median = flattened_coordinates[length // 2]
    return round(median)

def calculate_fuel_consumption(coordinates, median):
    total_fuel_consumption = 0
    for coordinate in coordinates:
        for value in coordinate:
            total_fuel_consumption += abs(value - median)
    return round(total_fuel_consumption)

def main():
    filename = 'sample_input.txt'
    coordinates = read_coordinates(filename)
    if coordinates:
        median = calculate_median(coordinates)
        print(f"Median coordinate: {median}")
        fuel_consumption = calculate_fuel_consumption(coordinates, median)
        print(f"Total fuel consumption: {fuel_consumption}")

if __name__ == "__main__":
    main()
```

