To create a Python script that generates a changelog for a given version of the Apache Arrow project from its JIRA issues, you can use the following code. This script uses the `jira` library to interact with the JIRA API and the `os` library to handle environment variables.

First, make sure to install the required library by running:

```bash
pip install jira
```

Now, create a file named `make_changelog.py` and paste the following code:

```python
import os
import sys
from jira import JIRA

def get_issues(jira, fix_version):
    try:
        return jira.search_issues(f"fixVersion={fix_version} AND resolution in (Fixed, Done)", expand="changelog")
    except Exception as e:
        print(f"Error fetching issues: {e}")
        return []

def group_issues_by_type(issues):
    grouped_issues = {}
    for issue in issues:
        issue_type = issue.fields.issuetype.name
        if issue_type not in grouped_issues:
            grouped_issues[issue_type] = []
        grouped_issues[issue_type].append(issue)
    return grouped_issues

def group_issues_by_category(issues):
    grouped_issues = {}
    for issue in issues:
        category = issue.fields.customfield_10008  # Replace 'customfield_10008' with the appropriate custom field ID for the category
        if category not in grouped_issues:
            grouped_issues[category] = []
        grouped_issues[category].append(issue)
    return grouped_issues

def format_markdown(grouped_issues):
    changelog = ""
    for issue_type, issues in grouped_issues.items():
        changelog += f"### {issue_type}\n"
        for issue in sorted(issues, key=lambda x: x.key):
            changelog += f"- [{issue.key}](https://issues.apache.org/jira/browse/{issue.key}): {issue.fields.summary}\n"
    return changelog

def format_website(grouped_issues):
    changelog = "<ul>\n"
    for category, issues in grouped_issues.items():
        changelog += f"  <li><strong>{category}</strong>\n"
        changelog += "    <ul>\n"
        for issue in sorted(issues, key=lambda x: x.key):
            changelog += f"      <li><a href='https://issues.apache.org/jira/browse/{issue.key}'>{issue.key}</a>: {issue.fields.summary}</li>\n"
        changelog += "    </ul>\n"
        changelog += "  </li>\n"
    changelog += "</ul>\n"
    return changelog

def main():
    if len(sys.argv) < 2:
        print("Usage: make_changelog.py $FIX_VERSION [$IS_WEBSITE]")
        return

    fix_version = sys.argv[1]
    is_website = len(sys.argv) > 2 and sys.argv[2] == "1"

    jira_username = os.getenv("JIRA_USERNAME")
    jira_password = os.getenv("JIRA_PASSWORD")

    if not jira_username or not jira_password:
        print("Error: JIRA_USERNAME and JIRA_PASSWORD environment variables must be set.")
        return

    try:
        jira = JIRA("https://issues.apache.org/jira", basic_auth=(jira_username, jira_password))
        issues = get_issues(jira, fix_version)

        if is_website:
            grouped_issues = group_issues_by_category(issues)
            changelog = format_website(grouped_issues)
        else:
            grouped_issues = group_issues_by_type(issues)
            changelog = format_markdown(grouped_issues)

        print(changelog)

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

Replace `'customfield_10008'` with the appropriate custom field ID for the category if you want to group issues by category for the website output.

To use the script, set the `JIRA_USERNAME` and `JIRA_PASSWORD` environment variables and run the script with the desired version and an optional argument for website output:

```bash
export JIRA_USERNAME=your_username
export JIRA_PASSWORD=your_password
python make_changelog.py 1.0.0 1
```

This will generate a changelog for version 1.0.0 formatted for the website. If you omit the second argument, the script will generate a markdown-formatted changelog.

