            if text:
                return text
            else:
                return f"Echo: {self.bot.nickname}"
        else:
            return None

    def handle_message(self, message):
        response = self.handle_cmd_echo(message)
        if response:
            self.bot.connection.msg_privmsg(response)

class Connection:
    def msg_privmsg(self, message):
        print(f"PRIVMSG: {message}")

class Bot:
    def __init__(self, nickname):
        self.nickname = nickname
        self.connection = Connection()
        self.modules = [EchoModule(self)]

    def handle_message(self, message):
        for module in self.modules:
            module.handle_message(message)

