def find_diagonal_order(matrix):
    if not all(isinstance(row, list) and all(isinstance(i, int) for i in row) for row in matrix):
        raise ValueError("Input must be a 2D list of integers")

    result = []
    m, n = len(matrix), len(matrix[0])
    up = True

    i, j = 0, 0
    while i < m and j < n:
        result.append(matrix[i][j])
        if up:
            if j == n - 1:
                i += 1
                up = False
            elif i == 0:
                j += 1
                up = False
            else:
                i -= 1
                j += 1
        else:
            if i == m - 1:
                j += 1
                up = True
            elif j == 0:
                i += 1
                up = True
            else:
                i += 1
                j -= 1

    return result
```

