import datetime
import dateutil.parser
import sys

class CongressError(Exception):
    def __init__(self, message, response=None, url=None):
        super().__init__(message)
        self.response = response
        self.url = url

class NotFound(CongressError):
    pass

def check_chamber(chamber):
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError(f"Invalid chamber: {chamber}")

def get_congress(year):
    if year < 1789:
        raise CongressError(f"Invalid year: {year}")
    return (year - 1788) // 2 + 1

def parse_date(date_str):
    try:
        return dateutil.parser.parse(date_str)
    except (AttributeError, ImportError):
        try:
            return datetime.datetime.strptime(date_str, "%Y-%m-%d")
        except ValueError:
            return datetime.datetime.strptime(date_str, "%Y-%m-%d %H:%M:%S")

def u(text):
    if isinstance(text, bytes):
        text = text.decode('utf-8')
    return text.replace('\r\n', '\n')

def get_offset(page):
    if page < 1:
        raise CongressError(f"Invalid page number: {page}")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.datetime.now().year)
