import pandas as pd
import numpy as np
from scipy.stats import pearsonr

class LinearPearsonAnomalyDetector:
    def __init__(self):
        self.data = pd.DataFrame(columns=['index', 'value'])
        self.correlation_threshold = None

    def train(self, values):
        if not values:
            raise ValueError("Input list cannot be empty.")
        if not all(isinstance(x, (int, float)) for x in values):
            raise ValueError("All values in the input list must be numerical.")

        self.data = pd.DataFrame({'index': range(1, len(values) + 1), 'value': values})
        self.correlation_threshold = abs(pearsonr(self.data['index'], self.data['value'])[0])

    def is_anomalous(self, value):
        if not isinstance(value, (int, float)):
            raise ValueError("Input value must be a numerical type.")

        new_row = {'index': len(self.data) + 1, 'value': value}
        self.data = self.data.append(new_row, ignore_index=True)

        new_correlation = abs(pearsonr(self.data['index'], self.data['value'])[0])
        return new_correlation < self.correlation_threshold
```

