```python
from typing import List, Callable, Dict, Any
from voip_controller import VoIPController

class VoIPManager:
    def __init__(self):
        self.calls: Dict[int, VoIPController] = {}

    def start_call(self, call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool):
        if not isinstance(call_id, int):
            raise ValueError("Call ID must be an integer")
        if not isinstance(endpoints, list) or not all(isinstance(endpoint, Endpoint) for endpoint in endpoints):
            raise ValueError("Endpoints must be a list of Endpoint objects")
        if not isinstance(encryption_key, bytes):
            raise ValueError("Encryption key must be bytes")
        if not isinstance(is_outgoing, bool):
            raise ValueError("Direction must be a boolean")

        if call_id in self.calls:
            raise ValueError("Call ID already exists")

        controller = VoIPController(endpoints, encryption_key, is_outgoing)
        self.calls[call_id] = controller
        controller.start()

    def end_call(self, call_id: int):
        if call_id not in self.calls:
            raise ValueError("Call ID does not exist")

        controller = self.calls[call_id]
        controller.end()
        del self.calls[call_id]

    def get_call_duration(self, call_id: int) -> float:
        if call_id not in self.calls:
            raise ValueError("Call ID does not exist")

        controller = self.calls[call_id]
        return controller.get_duration()

    def set_call_state_changed_handler(self, call_id: int, handler: Callable[[CallState], None]):
        if call_id not in self.calls:
            raise ValueError("Call ID does not exist")

        controller = self.calls[call_id]
        controller.set_state_changed_handler(handler)

    def set_call_audio_frame_handlers(self, call_id: int, send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None]):
        if call_id not in self.calls:
            raise ValueError("Call ID does not exist")

        controller = self.calls[call_id]
        controller.set_audio_frame_handlers(send_handler, recv_handler)
```

