Here is the code for the Flask application:

```python
from flask import Flask, request, jsonify
import numpy as np
import pandas as pd
from scipy import stats

app = Flask(__name__)

@app.route('/ztest', methods=['POST'])
def ztest():
    data = request.get_json()
    if 'sample1' not in data or 'sample2' not in data:
        return jsonify({'error': 'Both sample1 and sample2 are required'}), 400

    sample1 = np.array(data['sample1'])
    sample2 = np.array(data['sample2'])

    if len(sample1) < 30 or len(sample2) < 30:
        return jsonify({'error': 'Each sample should contain more than 30 unique values'}), 400

    if len(sample1) == len(sample2):
        result = stats.ttest_ind(sample1, sample2, equal_var=True)
    else:
        result = stats.ttest_ind(sample1, sample2, equal_var=False)

    return jsonify({'z_score': result.statistic, 'p_value': result.pvalue})

@app.route('/ttest-equalvariance', methods=['POST'])
def ttest_equalvariance():
    data = request.get_json()
    if 'sample1' not in data or 'sample2' not in data:
        return jsonify({'error': 'Both sample1 and sample2 are required'}), 400

    sample1 = np.array(data['sample1'])
    sample2 = np.array(data['sample2'])

    result = stats.ttest_ind(sample1, sample2, equal_var=True)

    return jsonify({'t_score': result.statistic, 'p_value': result.pvalue})

@app.route('/ttest-unequalvariance', methods=['POST'])
def ttest_unequalvariance():
    data = request.get_json()
    if 'sample1' not in data or 'sample2' not in data:
        return jsonify({'error': 'Both sample1 and sample2 are required'}), 400

    sample1 = np.array(data['sample1'])
    sample2 = np.array(data['sample2'])

    result = stats.ttest_ind(sample1, sample2, equal_var=False)

    return jsonify({'t_score': result.statistic, 'p_value': result.pvalue})

@app.route('/normaltest', methods=['POST'])
def normaltest():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    result = stats.normaltest(sample)

    return jsonify({'statistic': result.statistic, 'p_value': result.pvalue})

@app.route('/outliertest', methods=['POST'])
def outliertest():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    q1 = np.percentile(sample, 25)
    q3 = np.percentile(sample, 75)
    iqr = q3 - q1

    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    outliers = sample[(sample < lower_bound) | (sample > upper_bound)]

    return jsonify({'outliers': outliers.tolist()})

@app.route('/histogram', methods=['POST'])
def histogram():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    hist, bins = np.histogram(sample, bins='auto')

    return jsonify({'histogram': hist.tolist(), 'bins': bins.tolist()})

@app.route('/zvalue', methods=['POST'])
def zvalue():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    mean = np.mean(sample)
    std = np.std(sample)

    z_scores = (sample - mean) / std

    return jsonify({'z_scores': z_scores.tolist()})

@app.route('/max', methods=['POST'])
def max_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    max_value = np.max(sample)

    return jsonify({'max_value': max_value})

@app.route('/min', methods=['POST'])
def min_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    min_value = np.min(sample)

    return jsonify({'min_value': min_value})

@app.route('/range', methods=['POST'])
def range_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    max_value = np.max(sample)
    min_value = np.min(sample)

    range_value = max_value - min_value

    return jsonify({'range_value': range_value})

@app.route('/kurtosis', methods=['POST'])
def kurtosis_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    kurtosis_value = stats.kurtosis(sample)

    return jsonify({'kurtosis_value': kurtosis_value})

@app.route('/skew', methods=['POST'])
def skew_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    skew_value = stats.skew(sample)

    return jsonify({'skew_value': skew_value})

@app.route('/variance', methods=['POST'])
def variance_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    variance_value = np.var(sample)

    return jsonify({'variance_value': variance_value})

@app.route('/std', methods=['POST'])
def std_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    std_value = np.std(sample)

    return jsonify({'std_value': std_value})

@app.route('/mean', methods=['POST'])
def mean_value():
    data = request.get_json()
    if 'sample' not in data:
        return jsonify({'error': 'Sample is required'}), 400

    sample = np.array(data['sample'])

    mean_value = np.mean(sample)

    return jsonify({'mean_value': mean_value})

if __name__ == '__main__':
    app.run(debug=True)
