import re
import datetime

class DomainValidator:
    @staticmethod
    def is_valid_domain(domain):
        pattern = re.compile(r"^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$")
        return all(pattern.match(part) for part in domain.split("."))

    @staticmethod
    def is_valid_ip(ip):
        pattern = re.compile(r"^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$")
        return pattern.match(ip) is not None

    @staticmethod
    def format_date(date_str):
        months = {
            "jan": "Jan", "feb": "Feb", "mar": "Mar", "apr": "Apr",
            "may": "May", "jun": "Jun", "jul": "Jul", "aug": "Aug",
            "sep": "Sep", "oct": "Oct", "nov": "Nov", "dec": "Dec"
        }
        try:
            date = datetime.datetime.strptime(date_str, "%d-%b-%Y")
            return date.strftime("%d-%b-%Y").upper()
        except ValueError:
            for month in months:
                if month in date_str.lower():
                    date_str = date_str.replace(month, months[month])
            try:
                date = datetime.datetime.strptime(date_str, "%d-%b-%Y")
                return date.strftime("%d-%b-%Y").upper()
            except ValueError:
                return "Invalid date format"

    @staticmethod
    def convert_month(month):
        months = {
            "jan": "Jan", "feb": "Feb", "mar": "Mar", "apr": "Apr",
            "may": "May", "jun": "Jun", "jul": "Jul", "aug": "Aug",
            "sep": "Sep", "oct": "Oct", "nov": "Nov", "dec": "Dec"
        }
        return months.get(month.lower(), "Invalid month")

    @staticmethod
    def add_leading_zeros(number):
        return f"{int(number):02}"
