```python
from app import app

@app.route('/')
def index():
    return render_template('index.html')
```

5. Create a new file named `socketio_handlers.py` and add the following code to define the Socket.IO event handlers:

```python
from flask_socketio import emit
from app import socketio

votes = {'yes': 0, 'no': 0, 'maybe': 0}

@socketio.on('submit vote')
def handle_vote(data):
    vote = data.get('vote')
    if vote in ['yes', 'no', 'maybe']:
        votes[vote] += 1
        emit('update vote totals', votes, broadcast=True)
    else:
        emit('error', {'message': 'Invalid vote selection.'})
```

6. Create a new file named `templates/index.html` and add the following code to create the HTML page:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Vote App</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/socket.io/4.4.0/socket.io.js"></script>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
</head>
<body>
    <h1>Vote on the question:</h1>
    <p>Should we go for a walk?</p>
    <form id="vote-form">
        <label>
            <input type="radio" name="vote" value="yes"> Yes
        </label>
        <label>
            <input type="radio" name="vote" value="no"> No
        </label>
        <label>
            <input type="radio" name="vote" value="maybe"> Maybe
        </label>
        <button type="submit">Submit Vote</button>
    </form>
    <div id="vote-totals"></div>

    <script>
        const socket = io();

        socket.on('connect', () => {
            console.log('Connected to Socket.IO server.');
        });

        socket.on('update vote totals', (data) => {
            const voteTotals = document.getElementById('vote-totals');
            voteTotals.innerHTML = '';
            for (const [option, count] of Object.entries(data)) {
                voteTotals.innerHTML += `<p>${option}: ${count}</p>`;
            }
        });

        socket.on('error', (data) => {
            alert(data.message);
        });

        document.getElementById('vote-form').addEventListener('submit', (event) => {
            event.preventDefault();
            const vote = document.querySelector('input[name="vote"]:checked').value;
            socket.emit('submit vote', { vote });
        });
    </script>
</body>
</html>
