```python
class Model:
    def __init__(self, name):
        self.name = name

class News(Model):
    def __init__(self):
        super().__init__(name="News")

class Author(Model):
    def __init__(self):
        super().__init__(name="Author")

class AdminSite:
    def __init__(self):
        self.registry = {}

    def register(self, model):
        if not issubclass(model, Model):
            raise TypeError(f"{model.__name__} is not a valid model type.")

        if model.__name__ in self.registry:
            print(f"Model {model.__name__} is already registered.")
            return

        self.registry[model.__name__] = model
        print(f"Model {model.__name__} registered successfully.")

    def get_registered_models(self):
        return list(self.registry.keys())

# Usage
admin_site = AdminSite()

news_model = News()
author_model = Author()

admin_site.register(news_model.__class__)
admin_site.register(author_model.__class__)
admin_site.register(news_model.__class__)  # This will print "Model News is already registered."

print("Registered models:", admin_site.get_registered_models())
```

