import click
import textwrap
import sys

def title(text, underline_char='-', title_case=True):
    if title_case:
        text = text.title()
    underline = underline_char * len(text)
    click.echo(f"{text}\n{underline}")

def box(text, border_char='*'):
    lines = textwrap.wrap(text, width=70)
    border = border_char * (len(lines[0]) + 2)
    click.echo(f"\n{border}\n{border_char} {lines[0]} {border_char}\n{border}")
    for line in lines[1:]:
        click.echo(f"{border_char} {line} {border_char}")
    click.echo(f"{border}\n")

def evaluation(verbose=False):
    # Simulate the output of an evaluation process
    if verbose:
        click.echo("Detailed evaluation output...")
    else:
        click.echo("Evaluation summary...")

def summary(evaluation):
    # Print a summary of the evaluation
    if evaluation:
        click.echo("Evaluation successful.")
    else:
        click.echo("Evaluation failed.")

@click.group()
def cli():
    pass

@cli.command()
@click.option('--text', required=True, help='The text to be displayed as a title.')
@click.option('--underline-char', default='-', help='The character to be used for the underline.')
@click.option('--title-case', is_flag=True, help='Transform the text to title case.')
def title(text, underline_char, title_case):
    title(text, underline_char, title_case)

@cli.command()
@click.option('--text', required=True, help='The text to be displayed inside a box.')
@click.option('--border-char', default='*', help='The character to be used for the box border.')
def box(text, border_char):
    box(text, border_char)

@cli.command()
@click.option('--verbose', is_flag=True, help='Display detailed evaluation output.')
def evaluation(verbose):
    evaluation(verbose)

@cli.command()
@click.option('--evaluation', is_flag=True, help='Display the evaluation summary.')
def summary(evaluation):
    summary(evaluation)

if __name__ == '__main__':
    cli()
```

