```python
from collections import deque

def minimum_bridge_length(n, arr):
    if not all(len(row) == n for row in arr) or not all(0 <= x <= 1 for row in arr for x in row):
        return -1

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False]*n for _ in range(n)]
    queue = deque()
    min_length = float('inf')

    for i in range(n):
        for j in range(n):
            if arr[i][j] == 1 and not visited[i][j]:
                queue.append((i, j))
                visited[i][j] = True
                while queue:
                    x, y = queue.popleft()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                            if arr[nx][ny] == 0:
                                queue.append((nx, ny))
                                visited[nx][ny] = True
                            elif arr[nx][ny] == 1:
                                min_length = min(min_length, abs(x - nx) if dx == 0 else abs(y - ny))
    return -1 if min_length == float('inf') else min_length
```

