class Device:
    def __init__(self, name):
        self.name = name
        self.state = "UNAVAILABLE"

    def set_state(self, state):
        if self.state != "UNAVAILABLE":
            self.state = state

    def get_state(self):
        return self.state

class Switch(Device):
    def __init__(self, name):
        super().__init__(name)

    def turn_on(self):
        self.set_state("ON")

    def turn_off(self):
        self.set_state("OFF")

class Cover(Device):
    def __init__(self, name):
        super().__init__(name)

    def open(self):
        self.set_state("OPEN")

    def close(self):
        self.set_state("CLOSED")

    def toggle(self):
        if self.get_state() == "OPEN":
            self.close()
        elif self.get_state() == "CLOSED":
            self.open()

class SmartHomeSystem:
    def __init__(self):
        self.devices = {}

    def add_device(self, device):
        self.devices[device.name] = device

    def get_device_state(self, device_name):
        if device_name in self.devices:
            return self.devices[device_name].get_state()
        else:
            return "Device not found"

    def change_device_state(self, device_name, state):
        if device_name in self.devices:
            if self.devices[device_name].get_state() != "UNAVAILABLE":
                if isinstance(self.devices[device_name], Switch):
                    if state == "ON":
                        self.devices[device_name].turn_on()
                    elif state == "OFF":
                        self.devices[device_name].turn_off()
                elif isinstance(self.devices[device_name], Cover):
                    if state == "OPEN":
                        self.devices[device_name].open()
                    elif state == "CLOSED":
