class MockSDEClient:
    def __init__(self):
        self.stations = {
            "Station 1": {"stationID": 1, "regionID": 101},
            "Station 2": {"stationID": 2, "regionID": 102},
            "Station 3": {"stationID": 3, "regionID": 103},
        }

    def getStations(self, stationName):
        if stationName in self.stations:
            return [self.stations[stationName]]
        else:
            return []

class Station:
    def __init__(self, sde_client, station_name):
        if not isinstance(station_name, str) or not station_name:
            raise ValueError("Station name must be a non-empty string.")
        self.sde_client = sde_client
        self.station_name = station_name
        self.station_id = self.find_station_id()
        self.region_id = self.find_region_id()
        self.shorthand = self.generate_shorthand()

    def find_station_id(self):
        stations = self.sde_client.getStations(self.station_name)
        if stations:
            return stations[0]['stationID']
        else:
            raise ValueError(f"Station '{self.station_name}' not found.")

    def find_region_id(self):
        try:
            return self.sde_client.getStations(self.station_name)[0]['regionID']
        except (IndexError, KeyError):
            raise ValueError(f"Region ID not found for station '{self.station_name}'.")

    def generate_shorthand(self):
        return self.station_name.split()[0]

    def get_station_name(self):
        return self.station_name

    def get_station_id(self):
        return self.station_id

    def get_region_id(self):
        return self.region_id

    def get_shorthand(self):
        return self.shorthand
