```python
class Album:
    def __init__(self, title, artist, year, genre):
        self.title = title
        self.artist = artist
        self.year = year
        self.genre = genre

class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        if not isinstance(title, str) or not isinstance(artist, str) or not isinstance(year, int) or not isinstance(genre, str):
            raise ValueError("Invalid input data types")
        self.albums.append(Album(title, artist, year, genre))
        print("Album added successfully!")

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        results = []
        for album in self.albums:
            if option == "title":
                if album.title == value:
                    results.append(album)
            elif option == "artist":
                if album.artist == value:
                    results.append(album)
            elif option == "year":
                if album.year == value:
                    results.append(album)
            elif option == "genre":
                if album.genre == value:
                    results.append(album)
        return results

def main():
    album_service = AlbumService()
    while True:
        print("\n1. Add a new album to the collection.")
        print("2. Get all albums in the collection.")
        print("3. Search for an album.")
        print("4. Quit the program.")
        try:
            choice = int(input("Enter your choice: "))
            if choice == 1:
                title = input("Enter the album title: ")
                artist = input("Enter the artist name: ")
                year = int(input("Enter the year of release: "))
                genre = input("Enter the genre: ")
                album_service.add_record(title, artist, year, genre)
            elif choice == 2:
                albums = album_service.get_all_albums()
                for album in albums:
                    print(f"Title: {album.title}, Artist: {album.artist}, Year: {album.year}, Genre: {album.genre}")
            elif choice == 3:
                option = input("Enter the search criteria (title, artist, year, genre): ")
                value = input(f"Enter the value for {option}: ")
                results = album_service.search_by_option(option, value)
                for result in results:
                    print(f"Title: {result.title}, Artist: {result.artist}, Year: {result.year}, Genre: {result.genre}")
            elif choice == 4:
                print("Goodbye!")
                break
            else:
                print("Invalid choice. Please try again.")
        except ValueError as e:
            print(e)

if __name__ == "__main__":
    main()
