       task.title = title
       task.description = description
       db.session.commit()

       return make_response(jsonify({'message': 'Task updated successfully'}), 200)

   @app.route('/api/v2/tasks/<int:task_id>', methods=['DELETE'])
   @jwt_required
   def delete_task(task_id):
       current_user = get_jwt_identity()
       task = TaskModel.query.filter_by(id=task_id, user_id=current_user).first()

       if not task:
           return make_response(jsonify({'error': 'Task not found'}), 404)

       db.session.delete(task)
       db.session.commit()

       return make_response(jsonify({'message': 'Task deleted successfully'}), 200)
