   from flask import Flask
   from .config import Config
   from .models import db
   from .routes import jwt, app

   def create_app():
       app = Flask(__name__)
       app.config.from_object(Config)
       db.init_app(app)
       jwt.init_app(app)

       from .routes import register, login, refresh, identity, create_task, get_user_tasks, modify_task, delete_task

       app.register_blueprint(register)
       app.register_blueprint(login)
       app.register_blueprint(refresh)
