```python
import sys
import os

def read_tasks():
    if not os.path.exists("todo.txt"):
        open("todo.txt", "w").close()

    with open("todo.txt", "r") as file:
        return file.readlines()

def write_tasks(tasks):
    with open("todo.txt", "w") as file:
        file.writelines(tasks)

def add_task(description):
    tasks = read_tasks()
    tasks.append(f"[ ] {description}\n")
    write_tasks(tasks)

def list_tasks():
    tasks = read_tasks()
    for i, task in enumerate(tasks, start=1):
        print(f"{i}. {task.strip()}")

def mark_done(task_number):
    tasks = read_tasks()
    if 1 <= task_number <= len(tasks):
        tasks[task_number - 1] = tasks[task_number - 1].replace("[ ]", "[x]", 1)
        write_tasks(tasks)
    else:
        print("Invalid task number.")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: todo.py add \"task description\" | list | done task_number")
        sys.exit(1)

    command = sys.argv[1]

    if command == "add":
        if len(sys.argv) < 3:
            print("Usage: todo.py add \"task description\"")
            sys.exit(1)
        add_task(' '.join(sys.argv[2:]))
    elif command == "list":
        list_tasks()
    elif command == "done":
        if len(sys.argv) < 3:
            print("Usage: todo.py done task_number")
            sys.exit(1)
        try:
            task_number = int(sys.argv[2])
            mark_done(task_number)
        except ValueError:
            print("Invalid task number.")
    else:
        print("Invalid command.")
```

To use this script, save it as `todo.py` and run it from the command line with the appropriate arguments. For example:

```
python todo.py add "Task 1 description"
python todo.py list
python todo.py done 1
```

