class ScanManager:
    def __init__(self):
        self.scan_types = {}

    def register_scan(self, scan_type, file_extensions):
        self.scan_types[tuple(file_extensions)] = scan_type

    def execute_scan(self, file_path):
        _, file_extension = os.path.splitext(file_path)
        file_extension = file_extension.lower()

        for extensions, scan_type in self.scan_types.items():
            if file_extension in extensions:
                return scan_type().execute(file_path)

        raise ValueError(f"Unsupported file extension: {file_extension}")

