import math
from typing import List, Generator
import drawpi.config as config

def steps_to_mm(steps: int) -> float:
    """Converts the number of steps taken by a stepper motor into millimeters."""
    if steps < 0:
        raise ValueError("Number of steps cannot be negative.")
    return steps / config.STEPS_MM

def mm_to_steps(mm: float) -> int:
    """Converts a distance in millimeters into the number of steps a stepper motor needs to take."""
    if mm < 0:
        raise ValueError("Distance in millimeters cannot be negative.")
    return round(mm * config.STEPS_MM)

def chunks(l: List, n: int) -> Generator:
    """Splits a given list into chunks of size n."""
    if n <= 0:
        raise ValueError("Chunk size must be greater than zero.")
    for i in range(0, len(l), n):
        yield l[i:i + n]

def frequency_to_delay(frequency: float) -> int:
    """Converts a frequency in Hertz to a delay in microseconds between pulses."""
    if frequency <= 0:
        raise ValueError("Frequency must be greater than zero.")
    return round(1_000_000 / frequency)

def main():
    # Test cases for steps_to_mm
    print(f"100 steps = {steps_to_mm(100)} mm")
    print(f"0 steps = {steps_to_mm(0)} mm")

    # Test cases for mm_to_steps
