        numbers.append(num)

    total = sum(numbers)
    fortune = ""

    if len(str(total)) > 3:
        fortune = "average future"
    elif len(str(total)) == 3:
        fortune = "great future"
    else:
        fortune = "poor future"

    print(f"\nThe sum of your numbers is {total}.")
