```python
import os
import requests

def post_message_to_slack_channel(channel_id, message):
    # Validate channel_id and message parameters
    if not isinstance(channel_id, str) or not channel_id.strip():
        return {"error": "Invalid channel_id. It should be a non-empty string."}

    if not isinstance(message, str) or not message.strip():
        return {"error": "Invalid message. It should be a non-empty string."}

    # Get the Slack bot token from the environment variable
    slack_bot_token = os.getenv("SLACK_BOT_TOKEN")

    if not slack_bot_token:
        return {"error": "Slack bot token not found. Please set the SLACK_BOT_TOKEN environment variable."}

    # Construct the Slack API URL
    slack_api_url = f"https://slack.com/api/chat.postMessage"

    # Set the request headers
    headers = {
        "Authorization": f"Bearer {slack_bot_token}",
        "Content-Type": "application/json"
    }

    # Set the request payload
    payload = {
        "channel": channel_id,
        "text": message
    }

    try:
        # Send the HTTP request to the Slack API
        response = requests.post(slack_api_url, headers=headers, json=payload)

        # Check if the request was successful
        if response.status_code == 200:
            return {"success": True, "response": response.json()}
        else:
            return {"success": False, "error": f"Failed to post message. Status code: {response.status_code}"}

    except requests.exceptions.RequestException as e:
        return {"success": False, "error": f"An error occurred while sending the request: {str(e)}"}
```

