import os
import sys
import stat

def change_permissions(path):
    try:
        if os.path.isdir(path):
            os.chmod(path, stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
            for root, dirs, files in os.walk(path):
                for dir in dirs:
                    os.chmod(os.path.join(root, dir), stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
                for file in files:
                    os.chmod(os.path.join(root, file), stat.S_IRUSR | stat.S_IWUSR | stat.S_IRGRP | stat.S_IWGRP | stat.S_IROTH | stat.S_IWOTH)
            print("Permissions successfully changed for all directories and files.")
        else:
            print("The specified path is not a directory.")
    except PermissionError:
        print("Insufficient permissions to change the permissions of directories and files.")
    except FileNotFoundError:
        print("The specified directory does not exist.")
    except Exception as e:
        print("An error occurred:", str(e))

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python script.py <root_directory>")
    else:
        root_directory = sys.argv[1]
        change_permissions(root_directory)
