class ClassifierFreeSampleModel(nn.Module):
    def __init__(self, model, cond_mask_prob):
        super().__init__()
        self.model = model
        assert cond_mask_prob > 0, "Model must be trained with a conditional mask probability greater than zero"
        self.cond_mask_prob = cond_mask_prob

    def forward(self, x, y, cond_mode='text', scale=None):
        assert cond_mode in ['text', 'action'], "cond_mode must be either 'text' or 'action'"

        if 'uncond' not in y:
            y_uncond = copy.deepcopy(y)
            y_uncond['uncond'] = True
        else:
            y_uncond = y

        if cond_mode == 'text':
            y_text = copy.deepcopy(y)
            y_text['uncond'] = False
        else:
            y_text = y

        x_uncond = self.model(x, y_uncond)
        x_cond = self.model(x, y_text)

        if scale is None:
            scale = y['scale']

        return (x_cond - x_uncond) * scale + x_uncond

    def forward_smd_final(self, x, y, cond_mode='text'):
        return self.forward(x, y, cond_mode, scale=1.5)

    def forward_correct(self, x, y, cond_mode='text'):
        assert cond_mode in ['text', 'action'], "cond_mode must be either 'text' or 'action'"

        if 'uncond' not in y:
            y_uncond = copy.deepcopy(y)
            y_uncond['uncond'] = True
        else:
            y_uncond = y

        if cond_mode == 'text':
            y_text = copy.deepcopy(y)
            y_text['uncond'] = False
        else:
            y_text = y

        x_uncond = self.model(x, y_uncond)
        x_cond = self.model(x, y_text)

        return (x_cond - x_uncond) * 1.8 + x_uncond

    def forward_average(self, x, y, kps_to_text_ratio=1.5):
        x_kps = self.forward(x, y, cond_mode='action', scale=y['scale'])
        x_text = self.forward(x, y, cond_mode='text', scale=y['scale'] * kps_to_text_ratio)

        return (x_kps + x_text) / 2
