Here is a Python program that simulates a simple ray tracing engine to determine if a ray intersects with a sphere in a 3D space. The program includes classes for a Sphere, Light, Camera, and Screen, ensuring proper code structure and modularity. The Sphere class has a method `ray_intersection` that takes two numpy arrays as arguments and returns the point of intersection if it exists, or `None` if the ray does not intersect the sphere. The program also includes unit tests that cover cases where the ray intersects the sphere at two points, one point, and does not intersect.

```python
import numpy as np
import unittest

class Sphere:
    def __init__(self, x, y, z, r):
        self.center = np.array([x, y, z])
        if r <= 0:
            raise ValueError("Radius must be a positive number")
        self.radius = r

    def ray_intersection(self, ray_direction, ray_origin):
        oc = ray_origin - self.center
        b = np.dot(oc, ray_direction)
        c = np.dot(oc, oc) - self.radius**2
        discriminant = b**2 - c
        if discriminant < 0:
            return None
        elif discriminant == 0:
            t = -b
            return ray_origin + t * ray_direction
        else:
            t1 = -b - np.sqrt(discriminant)
            t2 = -b + np.sqrt(discriminant)
            if t1 > 0:
                return ray_origin + t1 * ray_direction
            elif t2 > 0:
                return ray_origin + t2 * ray_direction
            else:
                return None

class Light:
    def __init__(self, x, y, z):
        self.position = np.array([x, y, z])

class Camera:
    def __init__(self, x, y, z):
        self.position = np.array([x, y, z])

class Screen:
    def __init__(self, x, y, z, width, height):
        self.center = np.array([x, y, z])
        self.width = width
        self.height = height

class TestSphere(unittest.TestCase):
    def test_ray_intersection(self):
        sphere = Sphere(0, 0, 0, 1)
        ray_direction = np.array([1, 0, 0])
        ray_origin = np.array([-2, 0, 0])
        intersection = sphere.ray_intersection(ray_direction, ray_origin)
        self.assertEqual(intersection, np.array([-1, 0, 0]))

        ray_direction = np.array([0, 1, 0])
        ray_origin = np.array([0, -2, 0])
        intersection = sphere.ray_intersection(ray_direction, ray_origin)
        self.assertEqual(intersection, np.array([0, -1, 0]))

        ray_direction = np.array([1, 1, 0])
        ray_origin = np.array([-1, -1, 0])
        intersection = sphere.ray_intersection(ray_direction, ray_origin)
        self.assertEqual(intersection, np.array([0, 0, 0]))

        ray_direction = np.array([1, 0, 0])
        ray_origin = np.array([2, 0, 0])
        intersection = sphere.ray_intersection(ray_direction, ray_origin)
        self.assertIsNone(intersection)

if __name__ == "__main__":
    unittest.main()
```

