```python
import wikipedia

class TCPclient:
    def __init__(self): name):
        self.name = name

    def send(self, message):
        print(f"{self.name}: {message}")

    def receive(self):
        return input()

def handle(search_term):
    try:
        summary = wikipedia.summary(search_term, sentences=3)
        return summary
    except wikipedia.exceptions.DisambiguationError as e:
        return f"DisambiguationError: {e}"
    except wikipedia.exceptions.PageError as e:
        return f"PageError: {e}"
    except Exception as e:
        return f"Error: {e}"

def isValid(input_text):
    return "Wikipedia" in input_text

def main():
    client = TCPclient("User")

    while True:
        input_text = client.receive()

        if isValid(input_text):
            search_term = input("Enter search term: ")

            if search_term.lower() == "wikipedia":
                client.send("Please enter a different search term.")
                continue

            result = handle(search_term)
            client.send(result)
        else:
            client.send("Invalid input. Please say 'Wikipedia' to start a search.")

if __name__ == "__main__":
    main()
```

To use this program, you'll need to install the `wikipedia` library by running `pip install wikipedia`. The program will prompt the user to enter a search term after detecting the trigger word "Wikipedia". It will then fetch the summary of the topic from Wikipedia and output the first three sentences. If the search term is not found or if there are any other errors, the program will handle the exceptions and provide an appropriate error message.

