    if not hexagram_dict:
        return

    hexagram = create_hexagram()
    hexagram_details = hexagram_dict.get(hexagram)
    if hexagram_details:
        print(f"Hexagram Number: {hexagram_details['hexagram_number']}")
        print(f"Hexagram Name: {hexagram_details['hexagram_name']}")
        print(f"Hexagram Description: {hexagram_details['hexagram_description']}")

        user_input = input("Would you like to open a webpage with more information about the drawn hexagram? (y/n): ").lower()
        if user_input == 'y':
            webbrowser.open(f"https://en.wikipedia.org/wiki/{hexagram_details['hexagram_name']}")
        elif user_input != 'n':
            print("Error: Invalid input. Please enter 'y' or 'n'.")
    else:
        print("Error: Unable to find the hexagram details.")

if __name__ == "__main__":
    main()
