```python
def read_reboot_steps(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            return [line.strip() for line in lines]
    except FileNotFoundError:
        print("File not found.")
        return []
    except Exception as e:
        print("Error reading file:", str(e))
        return []

def parse_reboot_step(step):
    operation, ranges = step.split(' ')
    ranges = ranges.split(',')
    x_range = ranges[0].split('=')[1].split('..')
    y_range = ranges[1].split('=')[1].split('..')
    z_range = ranges[2].split('=')[1].split('..')
    return operation, (int(x_range[0]), int(x_range[1])), (int(y_range[0]), int(y_range[1])), (int(z_range[0]), int(z_range[1]))

def apply_reboot_step(grid, operation, x_range, y_range, z_range):
    for x in range(x_range[0], x_range[1] + 1):
        for y in range(y_range[0], y_range[1] + 1):
            for z in range(z_range[0], z_range[1] + 1):
                if -50 <= x <= 50 and -50 <= y <= 50 and -50 <= z <= 50:
                    if operation == 'on':
                        grid[x][y][z] = True
                    else:
                        grid[x][y][z] = False

def count_on_cubes(grid):
    count = 0
    for x in range(-50, 51):
        for y in range(-50, 51):
            for z in range(-50, 51):
                if grid[x][y][z]:
                    count += 1
    return count

def main():
    file_path = 'reboot_steps.txt'  # Replace with the actual file path
    reboot_steps = read_reboot_steps(file_path)

    grid = [[[False for _ in range(-50, 51)] for _ in range(-50, 51)] for _ in range(-50, 51)]

    for step in reboot_steps:
        operation, x_range, y_range, z_range = parse_reboot_step(step)
        apply_reboot_step(grid, operation, x_range, y_range, z_range)

    on_cubes = count_on_cubes(grid)
    print("Number of cubes that are on:", on_cubes)

if __name__ == '__main__':
    main()
```

