import torch
from torchvision import models
from torchvision.transforms import Normalize

class FeatureExtractor:
    def __init__(self, architecture, pretrained=True):
        if architecture not in ['densenet', 'resnet']:
            raise ValueError("Unsupported architecture. Please choose either 'densenet' or 'resnet'.")

        self.architecture = architecture
        self.pretrained = pretrained

        if architecture == 'densenet':
            self.encoder = models.densenet121(pretrained=pretrained)
            self.feature_names = ['s0', 's1', 's2', 's3']
        elif architecture == 'resnet':
            self.encoder = models.resnet50(pretrained=pretrained)
            self.feature_names = ['s0', 's1', 's2', 's3', 's4']

        self.normalize = Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])

    def extract_features(self, images):
        features = {}

        if self.architecture == 'densenet':
            for i, layer in enumerate(self.encoder.features):
                if isinstance(layer, torch.nn.modules.container.Sequential):
                    features[self.feature_names[i]] = layer(self.normalize(images))
        elif self.architecture == 'resnet':
            for i, layer in enumerate(self.encoder.children()):
                if isinstance(layer, torch.nn.modules.container.Sequential):
                    features[self.feature_names[i]] = layer(self.normalize(images))

        return features
