```python
import numpy as np

def calculate_determinant(n):
    # Create the circular adjacency matrix
    A = np.zeros((n, n))
    for i in range(n):
        A[i][i] = 3
        if i < n - 1:
            A[i][i+1] = -1
            A[i+1][i] = -1
        else:
            A[i][0] = -1
            A[0][i] = -1

    # Perform Gaussian elimination without pivoting
    for i in range(n):
        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]

    # Calculate the determinant
    determinant = np.prod(np.diag(A))

    return int(determinant)

def main():
    try:
        n = int(input("Enter the number of vertices (n): "))
        if n < 1:
            print("Error: n must be a positive integer.")
        else:
            determinant = calculate_determinant(n)
            print("Determinant:", determinant)
    except ValueError:
        print("Error: Invalid input. Please enter a positive integer.")

if __name__ == "__main__":
    main()
```

