class CacheItem:
    def __init__(self, key):
        self.key = key
        self.value = None
        self.expiration = None

    def get_key(self):
        return self.key

    def get(self):
        if self.is_expired():
            return None
        return self.value

    def is_hit(self):
        return self.value is not None and not self.is_expired()

    def set(self, value):
        self.value = value

    def expires_at(self, timestamp):
        if not isinstance(timestamp, datetime):
            raise ValueError("Timestamp must be a datetime object")
        self.expiration = timestamp

    def expires_after(self, seconds):
        if not isinstance(seconds, (int, float)):
            raise ValueError("Seconds must be a numeric value")
        self.expiration = datetime.now() + timedelta(seconds=seconds)

    def is_expired(self):
        if self.expiration is None:
