from django.urls import path, re_path
from django.conf.urls import handler404, handler500
from django.contrib import admin

def generate_urlpatterns(pages, app_name):
    urlpatterns = []
    handler404_view = None
    handler500_view = None

    for page_name, view_func in pages:
        if page_name == 'admin':
            urlpatterns.append(path('admin/', admin.site.urls))
        elif page_name == '404':
            handler404_view = view_func
        elif page_name == '500':
            handler500_view = view_func
        else:
            urlpatterns.append(re_path(r'^{}/$'.format(page_name), view_func, name=page_name))

    if handler404_view:
        handler404 = handler404_view
    if handler500_view:
        handler500 = handler500_view

